const n={title:"TripReel - Ứng Dụng Hoạt Hình Du Lịch Miễn Phí: Biến Ảnh Thành Video Đẹp",description:"Tạo video du lịch tuyệt vời với bản đồ hoạt hình và lộ trình bay. Ứng dụng hoạt hình du lịch miễn phí với bản đồ lộ trình trái đất 3D. Tự động biến ảnh của bạn thành video du lịch đẹp. Quyền riêng tư trước tiên, hoạt động ngoại tuyến.",keywords:"ứng dụng hoạt hình du lịch, ứng dụng hoạt hình bản đồ du lịch, ứng dụng hoạt hình lộ trình du lịch, ứng dụng hoạt hình bay, người tạo video du lịch, video du lịch tự động, bản đồ du lịch hoạt hình, hoạt hình lộ trình bay, hoạt hình du lịch, hoạt hình trái đất, video tóm tắt du lịch, ảnh thành video, điểm nổi bật du lịch, ứng dụng du lịch miễn phí, người tạo video ngoại tuyến, ứng dụng du lịch riêng tư, video cuộn máy ảnh"},h={logoAlt:"Logo TripReel",appName:"TripReel",howItWorks:"Cách hoạt động",video:"Video",features:"Tính năng",theApp:"Ứng dụng"},t={badge:"Biến ảnh thành câu chuyện du lịch",title1:"Thư viện ảnh của bạn,",title2:"Được tận dụng tối đa",description:"TripReel tự động tạo video du lịch tuyệt đẹp từ vị trí của ảnh. Xem hành trình của bạn trở nên sống động với bản đồ lộ trình hoạt hình tuyệt đẹp và đường bay trên quả cầu 3D, trong khi dữ liệu của bạn vẫn riêng tư và an toàn.",secure:"100% an toàn",worksOffline:"Hoạt động ngoại tuyến",globeAlt:"Hoạt hình quả cầu TripReel"},i={title:"Cách hoạt động",subtitle:"Ba bước đơn giản để tạo video du lịch hoàn hảo",step1:{title:"Cho phép truy cập ảnh",description:"Cấp cho TripReel quyền truy cập vào thư viện ảnh của bạn. Ứng dụng chỉ đọc siêu dữ liệu vị trí, không có gì khác."},step2:{title:"Phát hiện chuyến đi tự động",description:"TripReel phân tích siêu dữ liệu vị trí và thông minh tìm các chuyến đi của bạn dựa trên ngày tháng và địa điểm."},step3:{title:"Tạo video của bạn",description:"Xem hành trình của bạn mở ra trên hoạt hình quả cầu đẹp mắt, sẵn sàng chia sẻ trên mạng xã hội."}},c={title:"Xem điều kỳ diệu xảy ra",subtitle:"Xem TripReel biến đổi thư viện ảnh của bạn thành video du lịch tuyệt vời như thế nào",caption:"Video du lịch cuối cùng của bạn sẽ trông như thế này"},o={title:"Mọi thứ bạn cần",subtitle:"Các tính năng mạnh mẽ được thiết kế cho du khách hiện đại",twoTap:{title:"Video du lịch hai chạm",description:"Tạo video tổng kết du lịch tuyệt đẹp từ thư viện ảnh chỉ với hai lần chạm. Không cần chỉnh sửa."},smartTrip:{title:"Phát hiện chuyến đi thông minh",description:"Tự động tìm và nhóm các chuyến đi của bạn bằng cách phân tích ngày tháng và siêu dữ liệu vị trí từ ảnh của bạn."},globe:{title:"Hoạt hình quả cầu tuyệt đẹp",description:"Xem hành trình của bạn trở nên sống động với quả cầu 3D tuyệt đẹp hiển thị các tuyến du lịch hoạt hình và đường bay của bạn trên toàn thế giới."},privacy:{title:"Quyền riêng tư trước tiên",description:"Mọi thứ được xử lý trên thiết bị của bạn. Ảnh của bạn không bao giờ rời khỏi điện thoại. Hoạt động ở chế độ máy bay."},customStyles:{title:"Phong cách tùy chỉnh",description:"Chọn từ nhiều phong cách trái đất và tùy chỉnh để phù hợp với thẩm mỹ của bạn và làm cho mỗi video trở nên độc đáo."},manualControl:{title:"Kiểm soát thủ công",description:"Bạn có thể thêm các chuyến đi hoàn toàn mới theo cách thủ công nếu dịch vụ vị trí không được bật trên thiết bị của bạn."}},g={title:"Ý tưởng video sáng tạo",subtitle:"Lấy cảm hứng từ những gì bạn có thể tạo bằng TripReel. Từ những chuyến đi cuối tuần ngắn đến những cuộc phiêu lưu cả năm, tạo video du lịch tuyệt đẹp cho mọi chuyến đi.",description:"Cho dù bạn đang tạo hoạt hình bản đồ du lịch, ghi lại tuyến bay hay làm video tổng kết du lịch cuối năm, TripReel giúp dễ dàng chuyển đổi kỷ niệm của bạn thành video có thể chia sẻ.",ideas:{yearRecap:{title:"Tổng kết du lịch 2025",description:"Tạo video tổng kết du lịch hàng năm 2025 của bạn một cách tự động"},europeRoadTrip:{title:"Chuyến đi châu Âu",description:"Trưng bày cuộc phiêu lưu châu Âu của bạn với bản đồ tuyến đường hoạt hình"},southeastAsia:{title:"Hành trình Đông Nam Á",description:"Hình dung tuyến đường ba lô của bạn qua nhiều quốc gia"},japanRail:{title:"Hành trình tàu hỏa Nhật Bản",description:"Tạo video bản đồ các tuyến tàu của bạn khắp Nhật Bản"},crossCountry:{title:"Xuyên Hoa Kỳ",description:"Biến chuyến đi đường bộ Mỹ của bạn thành video tuyến đường hoành tráng"},islandHopping:{title:"Nhảy đảo",description:"Hiển thị các chuyến đi từ đảo này sang đảo khác với hoạt hình 3D tuyệt đẹp"},worldTour:{title:"Montage tour thế giới",description:"Nhiều chuyến đi thành một video du lịch toàn cầu tuyệt vời"},travelPlans:{title:"Kế hoạch du lịch 2026",description:"Hình dung và lên kế hoạch các cuộc phiêu lưu du lịch thú vị của bạn cho năm 2026"},lifetimeTravel:{title:"Câu chuyện du lịch cả đời",description:"Tạo video trưng bày tất cả các chuyến đi trong đời bạn"},regionalExplorer:{title:"Nhà thám hiểm khu vực",description:"Vẽ bản đồ các cuộc phiêu lưu của bạn qua các tiểu bang, tỉnh và vùng"},festivalCircuit:{title:"Vòng quay lễ hội",description:"Vẽ bản đồ hành trình lễ hội âm nhạc và sự kiện của bạn"},bikeRoutes:{title:"Chuyến đi thành phố của tôi",description:"Trưng bày tất cả các chuyến trốn vào thành phố của bạn"}}},u={title:"Ứng dụng",subtitle:"Hiện có sẵn trên App Store",alt1:"Video du lịch tự động - Tạo video tuyệt đẹp trong vài giây",alt2:"Phát hiện vị trí ảnh - Sử dụng siêu dữ liệu của ảnh",alt3:"Phát hiện chuyến đi - Tự động nhóm các chuyến đi của bạn",alt4:"Video Trái Đất đẹp - Hoạt hình quả cầu về hành trình của bạn",alt5:"Phong cách tùy chỉnh - Cá nhân hóa video du lịch của bạn"},e={comingSoon:"Sắp ra mắt",androidTitle:"Ứng dụng Android sắp ra mắt!",androidMessage:'Phiên bản Android chưa có sẵn nhưng sẽ sớm có. Gửi tin nhắn cho tôi tại <a href="mailto:marian@qod.ee?subject=TripReel%20Android%20App" class="text-sky-600 dark:text-sky-400 hover:text-sky-700 dark:hover:text-sky-300 font-semibold transition-colors">marian@qod.ee</a> và tôi sẽ cho bạn biết khi nó sẵn sàng!',gotIt:"Đã hiểu!"},a={title:"Câu hỏi thường gặp",subtitle:"Mọi thứ bạn cần biết về TripReel",q1:{question:"Tôi có thực sự có thể sử dụng ứng dụng hoàn toàn ở chế độ máy bay không?",answer:"Có! Đối với người dùng cao cấp, ứng dụng có thể được sử dụng hoàn toàn ngoại tuyến ở chế độ máy bay mà không có giới hạn. Đối với người dùng không phải cao cấp, một số tính năng được hỗ trợ quảng cáo có thể yêu cầu bật internet tạm thời, nhưng đối với người dùng cao cấp không có quảng cáo và ứng dụng có thể được sử dụng hoàn toàn ở chế độ máy bay."},q2:{question:"Tôi đã nâng cấp lên Premium, làm cách nào để xóa hình mờ?",answer:"Nhiều người hỏi ứng dụng nào đã được sử dụng để tạo những video này, vì vậy, sau khi nâng cấp lên cao cấp, bạn có tùy chọn thêm phiên bản nhỏ hơn của hình mờ (chỉ với tên ứng dụng) hoặc xóa hoàn toàn nếu bạn muốn."},q3:{question:"Dữ liệu ảnh của tôi có an toàn và riêng tư không?",answer:"Hoàn toàn! TripReel chỉ đọc siêu dữ liệu vị trí từ ảnh của bạn - chúng tôi không bao giờ truy cập, lưu trữ hoặc truyền nội dung ảnh thực tế. Tất cả quá trình xử lý diễn ra cục bộ trên thiết bị của bạn và không có dữ liệu nào rời khỏi điện thoại của bạn. Bạn có thể xác minh điều này bằng cách sử dụng ứng dụng ở chế độ máy bay - nó hoạt động hoàn hảo ngoại tuyến!"},q4:{question:"Điều gì xảy ra nếu ảnh của tôi không có dữ liệu vị trí?",answer:"Không vấn đề gì! Nếu dịch vụ vị trí không được bật khi bạn chụp ảnh, bạn có thể tự tạo chuyến đi theo cách thủ công và tự thêm vị trí. Ứng dụng cho bạn toàn quyền kiểm soát để tùy chỉnh dòng thời gian du lịch của bạn."},q5:{question:"Ứng dụng phát hiện các chuyến đi của tôi tự động như thế nào?",answer:"TripReel phân tích siêu dữ liệu vị trí và dấu thời gian từ ảnh của bạn để thông minh xác định khi nào và ở đâu bạn đã đi du lịch. Nó nhóm các vị trí và ngày gần nhau lại để tự động phát hiện các chuyến đi của bạn mà không cần làm việc thủ công."},q6:{question:"Tôi có thể tùy chỉnh giao diện của video không?",answer:"Có! Bạn có thể chọn từ nhiều phong cách trái đất và tùy chỉnh các khía cạnh khác nhau của video du lịch hoạt hình để phù hợp với thẩm mỹ cá nhân của bạn. Người dùng cao cấp được truy cập vào các phong cách hoạt hình tuyến đường bổ sung, chủ đề bản đồ và tùy chọn đường bay."},q7:{question:"Tôi có cần tạo tài khoản không?",answer:"Không cần tài khoản! TripReel hoạt động ngay sau khi tải xuống. Không có đăng ký, không có đăng nhập và không cần thông tin cá nhân. Chỉ cần tải xuống ứng dụng và bắt đầu tạo video du lịch của bạn ngay lập tức."},q8:{question:"Tại sao một địa điểm bị thiếu trong chuyến đi của tôi?",answer:"Ứng dụng chỉ có thể hoạt động với dữ liệu có sẵn, vì vậy trước hết bạn cần ít nhất vài bức ảnh ở địa điểm đó. Thứ hai, bạn cần đảm bảo rằng bạn đã bật dữ liệu vị trí khi ở đó. Thứ ba, đôi khi tín hiệu GPS yếu có thể gây ra dữ liệu vị trí sai. Nếu bạn đã loại trừ tất cả những điều này và vị trí của bạn vẫn không hiển thị, bạn có thể thêm vị trí đó theo cách thủ công từ Trips Overview > nút Edit. Vui lòng cũng sử dụng Contact để báo cáo sự cố."},q9:{question:"Tôi có thể chia sẻ video tuyệt vời của mình ở đâu?",answer:"Tất nhiên, bạn cũng có thể chia sẻ nó trên tất cả các nền tảng xã hội. Để phù hợp hơn với nền tảng, ứng dụng cho phép tỷ lệ khung hình khác nhau cho video của bạn."},q10:{question:"Tôi có thể báo cáo lỗi ở đâu?",answer:"Chỉ cần liên hệ trực tiếp với tôi tại marian@qod.ee, giải thích ngắn gọn vấn đề là gì."}},r={title:"Hỗ trợ qua email",description:"Nếu bạn có bất kỳ phản hồi nào hoặc gặp bất kỳ vấn đề nào, vui lòng liên hệ trực tiếp với tôi qua email này và tôi sẽ đọc và xử lý yêu cầu của bạn càng nhanh càng tốt. Cảm ơn bạn đã sử dụng ứng dụng!",close:"Đóng"},d={default:{title:"🍪 Cookie",message:"Chúng tôi sử dụng cookie trên trang web TripReel để nâng cao trải nghiệm của bạn. Không thu thập dữ liệu cá nhân.",accept:"Chấp nhận",decline:"Từ chối",details:"Chi tiết"},theme:{title:"🍪 Cookie",message:"🌙 Để lưu tùy chọn chủ đề của bạn, bạn cần chấp nhận cookie thiết yếu trên trang web TripReel. Không có chúng, lựa chọn chủ đề của bạn không thể được lưu.",accept:"Chấp nhận",decline:"Từ chối",details:"Chi tiết"}},l={privacy:"Chính sách bảo mật ứng dụng",cookies:"Chính sách Cookie trang web",contact:"Liên hệ",cookiePreferences:"Tùy chọn Cookie",madeWith:"Được tạo với",forTravelers:"cho du khách trên toàn thế giới",copyright:"© {{year}} TripReel."},b={title:"Sẵn sàng chia sẻ hành trình của bạn?",description:"Tải xuống TripReel ngay hôm nay và biến thư viện ảnh của bạn thành video du lịch đẹp mắt với bản đồ và tuyến đường hoạt hình. Những cuộc phiêu lưu của bạn xứng đáng được kỷ niệm.",features:"Miễn phí tải xuống • Nhanh chóng & Tiện lợi • Đảm bảo quyền riêng tư"},y={title:"Giới thiệu về TripReel",subtitle:"Ứng dụng tạo video nổi bật chuyến đi chuyên nghiệp và ứng dụng hoạt hình tuyến đường",howItWorks:{title:"Ứng dụng tóm tắt chuyến đi của chúng tôi hoạt động như thế nào",description:"Ứng dụng hoạt hình chuyến đi sử dụng các thuật toán thông minh để quét dữ liệu GPS từ ảnh của bạn và tự động phát hiện các chuyến đi của bạn. Bộ tạo hoạt hình tuyến đường sau đó tạo ra các hoạt hình tuyến đường chuyến đi mượt mà, điện ảnh cho thấy con đường của bạn qua các thành phố, quốc gia và lục địa. Cho dù bạn đang tạo video nổi bật chuyến đi cuối tuần nhanh chóng hay video tóm tắt chuyến đi cả năm, ứng dụng bản đồ chuyến đi hoạt hình khiến việc này trở nên dễ dàng."},customization:{title:"Tùy chỉnh rộng rãi cho video hoạt hình chuyến đi của bạn",description:"Ứng dụng tạo câu chuyện du lịch cung cấp các tùy chọn tùy chỉnh cấp chuyên nghiệp để làm cho video bản đồ chuyến đi hoạt hình của bạn thực sự độc đáo:",features:{videoQuality:"Chọn giữa 30 FPS, 60 FPS hoặc cao cấp 90 FPS để có hoạt hình tuyến đường chuyến đi mượt mà như lụa trong video nổi bật chuyến đi của bạn",bitrate:"Điều chỉnh chất lượng video (tốc độ bit) từ bình thường đến cao cho video bản đồ chuyến đi trong suốt như pha lê không có hiện tượng nhiễu hình ảnh",earthStyles:"Chọn từ nhiều kiểu trái đất tuyệt đẹp bao gồm Chân thực, Ánh sáng ban đêm, Bản đồ ban ngày và chế độ xem Vệ tinh cho video bản đồ chuyến đi hoạt hình của bạn",borders:"Chuyển đổi đường biên giới quốc gia trên bộ tạo hoạt hình tuyến đường của bạn với màu sắc và độ dày có thể tùy chỉnh để trực quan hóa địa lý được cải thiện",aspectRatios:"Tạo video hoạt hình chuyến đi ở định dạng Dọc (9:16), Màn hình rộng (16:9), Rạp phim (2.35:1) hoặc Vuông (1:1) hoàn hảo cho Instagram, TikTok, YouTube và các nền tảng xã hội khác",tripSpeed:"Kiểm soát tốc độ bộ tạo hoạt hình tuyến đường giữa các địa điểm (lên đến 3500 km/s) để tạo video tóm tắt chuyến đi năng động hoặc thư giãn",pauseDuration:"Điều chỉnh thời lượng tạm dừng tại mỗi địa điểm (0,5-5 giây) để làm nổi bật các điểm đến quan trọng trong video nổi bật chuyến đi của bạn",locationLabels:"Hiển thị nhãn Thành phố, Khu vực và/hoặc Quốc gia trên video bản đồ chuyến đi hoạt hình của bạn để cung cấp bối cảnh cho chuyến đi của bạn",pathDisplay:"Chuyển đổi liệu bạn có muốn hiển thị tất cả các tuyến đường chuyến đi trước đó hay chỉ chuyến đi hiện tại trong hoạt hình tuyến đường chuyến đi của bạn"}}},s={meta:n,header:h,hero:t,howItWorks:i,videoSection:c,features:o,videoIdeas:g,screenshots:u,appStore:e,faq:a,contact:r,cookieBanner:d,footer:l,cta:b,about:y};export{y as about,e as appStore,r as contact,d as cookieBanner,b as cta,s as default,a as faq,o as features,l as footer,h as header,t as hero,i as howItWorks,n as meta,u as screenshots,g as videoIdeas,c as videoSection};
